const i = $input.first().json;
const userRaw = String(i.user_raw || 'anon');
const digits = userRaw.replace(/\D/g, '');
const userKey = digits || userRaw.replace(/[^a-zA-Z0-9]/g, '') || 'anon';
let text = String(i.text || '');
const found = [];
text = text.replace(/\b\d{3}[.\s]?\d{3}[.\s]?\d{3}[-.\s]?\d{2}\b/g, m => (found.push('cpf'), '[cpf_removido]'));
text = text.replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, m => (found.push('email'), '[email_removido]'));
text = text.replace(/\b\(?\d{2}\)?[.\s]?9?\d{4}[-.\s]?\d{4}\b/g, m => (found.push('phone'), '[fone_removido]'));
const ws = i.workspace || 'tds';
return [{ json: {
  sanitized: text.slice(0, 2000),
  user_key: userKey,
  channel: i.channel || 'unknown',
  remote_jid: i.remote_jid || '',
  instance: i.instance || '',
  conversation_id: i.conversation_id || null,
  account_id: i.account_id || null,
  access_token_used: !!i.access_token_used,
  workspace: ws,
  chars_in: String(i.text || '').length,
  pii_found: [...new Set(found)].join(',') || 'none',
  t0: Date.now(),
} }];

const it = $input.first().json;
const prev = $('Sanitizar PII').item.json;
const session_id = $('Hash Sessao').item.json.session_id || 'na';
const latency = Date.now() - prev.t0;
let ok = false, reply = '', status = it && it.statusCode ? it.statusCode : null, err = null, sources = 0;
const metrics = it && it.metrics ? it.metrics : {};
if (it && it.textResponse) {
  reply = String(it.textResponse).replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
  sources = (it.sources || []).length;
  ok = reply.length > 0;
  if (!ok) err = 'empty_textResponse';
} else if (it && it.error) err = String(typeof it.error === 'object' ? (it.error.message || JSON.stringify(it.error)) : it.error).slice(0, 280);
else err = 'no_textResponse status=' + status;
if (it && it.error && it.error.description) err = String(it.error.description).slice(0, 280);
const timeout = !!(err && /timeout|ETIMEDOUT|timed out|aborted|abort/i.test(err)) || status === 504 || status === 408;
return [{ json: {
  ok, reply_text: reply.slice(0, 4096), sources, latency_ms: latency, rag_status: status,
  tokens_in: metrics.prompt_tokens || 0, tokens_out: metrics.completion_tokens || 0,
  error: err, timeout, workspace: prev.workspace, channel: prev.channel,
  remote_jid: prev.remote_jid, instance: prev.instance,
  conversation_id: prev.conversation_id, account_id: prev.account_id,
  user_hash: session_id, session_id, pii_stripped: prev.pii_found,
  chars_in: prev.chars_in, chars_out: reply.length }}];
